export type Palette = Partial<{
    bg: string;
    surface: string;
    raised: string;
    card: string;
    ink: string;
    muted: string;
    line: string;
    rim: string;
    sys: string;
    cmd: string;
    fire: string;
    aim: string;
    attack: string;
    advance: string;
    fallin: string;
    flag: string;
    go: string;
    teamA: string;
    teamB: string;
    hurt: string;
    critical: string;
    /** Text / thin-line twins for the light theme (defaults to the face colour). */
    sysInk: string;
    cmdInk: string;
    fireInk: string;
}>;

export declare function mount(host: HTMLElement, css: string, opts?: {
    theme?: "dark" | "light";
